import json,subprocess,numpy as np,scipy.optimize as so,scipy.stats as stats
rng=np.random.default_rng(82935);cases=[];skipped=0
def evaluate(b,Z,t,e,efron,penalty):
 p=Z.shape[1];eta=Z@b;ll=0.;score=np.zeros(p);info=np.zeros((p,p))
 for time in np.unique(t[e==1]):
  risk=t>=time;events=(t==time)&(e==1);d=events.sum()
  shift=max(eta[risk]);w=np.exp(eta[risk]-shift);v=Z[risk];ew=np.exp(eta[events]-shift);ev=Z[events]
  ll+=(eta[events]-shift).sum();score+=ev.sum(0)
  for j in range(d):
   fraction=j/d if efron else 0.
   den=w.sum()-fraction*ew.sum();num=w@v-fraction*(ew@ev);second=np.einsum('n,ni,nj->ij',w,v,v)-fraction*np.einsum('n,ni,nj->ij',ew,ev,ev)
   ll-=np.log(den);score-=num/den;info+=second/den-np.outer(num,num)/den**2
 return ll-penalty*(b@b)/2,score-penalty*b,info+penalty*np.eye(p)
for _ in range(60):
 n=int(rng.integers(20,90));p=int(rng.integers(1,4));X=rng.normal(0,1,(n,p))*rng.uniform(.3,2,p)+rng.uniform(-10,10,p);effect=rng.normal(0,.3,p);t=np.ceil(rng.exponential(np.exp(-(X-X.mean(0))@effect))*3);e=(rng.random(n)<.75).astype(int);Z=(X-X.mean(0))/X.std(0,ddof=1)
 for efron in [False,True]:
  for penalty in [0.,.5]:
   r=so.root(lambda b:evaluate(b,Z,t,e,efron,penalty)[1],np.zeros(p),jac=lambda b:-evaluate(b,Z,t,e,efron,penalty)[2],tol=1e-11)
   if np.max(abs(evaluate(r.x,Z,t,e,efron,penalty)[1]))>1e-7:skipped+=1;continue
   coef=r.x/X.std(0,ddof=1);cov=np.linalg.inv(evaluate(r.x,Z,t,e,efron,penalty)[2])/X.std(0,ddof=1)[:,None]/X.std(0,ddof=1)[None,:];se=np.sqrt(cov.diagonal());ll=evaluate(r.x,Z,t,e,efron,0.)[0]
   times=sorted(np.unique(t[e==1]));hazards=np.cumsum([((t==tt)&(e==1)).sum()/np.exp((X[t>=tt]-X.mean(0))@coef).sum() for tt in times]);S=np.exp(-hazards)
   rows=np.c_[X,t,e];inp='cox_ph|'+str(int(efron))+','+str(penalty)+'|'+';'.join(','.join(map(str,row)) for row in rows)
   cases.append((inp,{'coefficients':coef,'standard_errors':se,'partial_log_likelihood':ll,'baseline_survival':S}))
proc=subprocess.run(['/private/tmp/rusta-ducksmiles-jmp-target/inference-check/cox_runner'],input='\n'.join(c[0] for c in cases)+'\n',text=True,capture_output=True,check=True)
errors=[];maxerror=(0,None)
for (inp,expected),out in zip(cases,proc.stdout.splitlines()):
 try:actual=json.loads(out)
 except Exception:errors.append(('runtime',out));continue
 for key,ee in expected.items():
  aa=np.asarray(actual[key]);ee=np.asarray(ee);error=float(np.max(np.abs(aa-ee)/np.maximum(1,np.abs(ee))))
  if error>maxerror[0]:maxerror=(error,key)
  if error>2e-7:errors.append((key,error))
print(json.dumps({'cases':len(cases),'oracle_nonidentifiable_skipped':skipped,'max_scaled_absolute_error':maxerror,'failure_count':len(errors),'errors':errors[:20]}))
